	@TestFactory
	List<DynamicTest> leafAndUnionsPreserveOrderedOccurrenceMultiplicity() {
		List<DynamicTest> tests = new ArrayList<>();
		for (String shape : List.of("E", "I", "EI", "IE", "EIE", "EE")) {
			tests.add(DynamicTest.dynamicTest(shape, () -> {
				Leaf explicit = new Leaf("E");
				Leaf inferred = new Leaf("I");
				SailDataset dataset = switch (shape) {
				case "E" -> explicit;
				case "I" -> inferred;
				case "EI" -> union(explicit, inferred);
				case "IE" -> union(inferred, explicit);
				case "EIE" -> union(explicit, union(inferred, explicit));
				case "EE" -> union(explicit, explicit);
				default -> throw new AssertionError(shape);
				};
				try (dataset) {
					assertEquals(shape.chars().mapToObj(c -> String.valueOf((char) c)).toList(),
							requiredShape(dataset).occurrences());
					assertEquals(0, explicit.statementOpens + inferred.statementOpens);
					assertEquals(0, explicit.closeCount + inferred.closeCount);
				}
			}));
		}
		return tests;
	}

