	private static SailDataset union(SailDataset first, SailDataset second) {
		return UnionSailDataset.getInstance(first, second);
	}

	private static <T> List<T> datasets(SailDataset dataset, Class<T> type) {
		return new SailDatasetTripleTermSource(SimpleValueFactory.getInstance(), dataset).getDatasets(type);
	}

	private static TripleSource source(SailDataset dataset) {
		return new SailDatasetTripleTermSource(SimpleValueFactory.getInstance(), dataset);
	}

	private static Optional<Shape> resolve(SailDataset dataset) {
		return SailDatasetReadComposition.resolve(source(dataset), Shape.class,
				SailDatasetReadCompositionTest::combine);
	}

	private static Shape requiredShape(SailDataset dataset) {
		return requiredShape(resolve(dataset));
	}

	private static Shape requiredShape(Optional<Shape> result) {
		assertTrue(result.isPresent(), "the complete supported source must expose its composition");
		return result.orElseThrow();
	}

	private static Optional<Shape> combine(Shape first, Shape second) {
		List<String> occurrences = new ArrayList<>(first.occurrences());
		occurrences.addAll(second.occurrences());
		return Optional.of(new Combined(List.copyOf(occurrences)));
	}

	private interface Shape {
		List<String> occurrences();
	}

	private record Combined(List<String> occurrences) implements Shape {
	}

